+import { minorUnitFactor } from "./money";
+
+interface ExportInvoice {
+  invoiceNumber: string;
+  company: { name: string };
+  currencyCode: string;
+  issueDate: Date | string;
+  dueDate: Date | string | null;
+  totalMinor: number;
+  paidMinor: number;
+  status: string;
+}
+
+export function invoiceCsv(invoices: ExportInvoice[]): string {
+  const quote = (value: string) => /[",\r\n]/.test(value) ? `"${value.replaceAll('"', '""')}"` : value;
+  const date = (value: Date | string | null) => value ? new Date(value).toISOString().slice(0, 10) : "";
+  const rows = invoices.map((i) => {
+    const currency = i.currencyCode.toUpperCase();
+    const factor = minorUnitFactor(currency);
+    const amount = (minor: number) => (minor / factor).toFixed(factor === 1 ? 0 : 2);
+    const balance = ["SENT", "PARTIAL", "OVERDUE"].includes(i.status) ? Math.max(0, i.totalMinor - i.paidMinor) : 0;
+    return [i.invoiceNumber, i.company.name, currency, date(i.issueDate), date(i.dueDate), amount(i.totalMinor), amount(i.paidMinor), amount(balance), i.status].map(quote).join(",");
+  });
+  return "\uFEFF" + ["invoice_number,company,currency,issue_date,due_date,total,paid,balance_due,status", ...rows].join("\r\n") + "\r\n";
+}
