+export function agingReport(invoices: Invoice[], asOf: string) {
+  const day = (date: string | Date) => Date.parse(typeof date === "string" ? date.slice(0, 10) : date.toISOString().slice(0, 10)) / 86400000;
+  const rows = new Map<string, { currency: string; buckets: Record<Bucket, number>; totalMinor: number }>();
+  for (const invoice of invoices) {
+    if (!["SENT", "PARTIAL", "OVERDUE"].includes(invoice.status)) continue;
+    const balance = Math.max(0, invoice.totalMinor - invoice.paidMinor);
