+function phoneDigits(value?: string | null): string | null {
+  if (!value) return null;
+  let number = value.replace(/[\s.()\-]/g, "");
+  if (!/^\+?\d+$/.test(number)) return null;
+  if (number.startsWith("+")) number = number.slice(1);
+  else if (number.startsWith("00")) number = number.slice(2);
+  else if (number.startsWith("0")) number = "84" + number.slice(1);
+  return /^[1-9]\d{7,14}$/.test(number) ? number : null;
+}
+export function phoneUrl(value?: string | null): string | null {
+  const digits = phoneDigits(value);
+  return digits ? `tel:+${digits}` : null;
+}
+export function whatsappUrl(value?: string | null): string | null {
+  const digits = phoneDigits(value);
+  return digits ? `https://wa.me/${digits}` : null;
+}
+export function telegramUrl(value?: string | null): string | null {
+  if (!value) return null;
+  const name = value.trim().replace(/^(?:https?:\/\/)?t\.me\//, "").replace(/^@/, "").replace(/\/$/, "");
+  return /^[A-Za-z][A-Za-z0-9_]{4,31}$/.test(name) ? `https://t.me/${name}` : null;
+}
